    pytester: Pytester, monkeypatch: MonkeyPatch, mark: str
) -> None:
    """With --pdb, setUp and tearDown should not be called for skipped tests."""
    tracked: List[str] = []
    monkeypatch.setattr(pytest, "test_pdb_teardown_skipped", tracked, raising=False)

