        ) == ConditionSet(x, x + sin(x) > 1, S.Reals)

    assert solveset(Eq(sin(Abs(x)), x), x, domain=S.Reals
        ) == ConditionSet(x, Eq(-x + sin(Abs(x)), 0), S.Reals)

    assert solveset(y**x-z, x, S.Reals) == \
        ConditionSet(x, Eq(y**x - z, 0), S.Reals)

